r"""
tb_class3_v1 -- re-enumeration of the height-<= 3 resonance classes with an EXACT
realisability test, checking the predecessor's Theorem 5 count.

reports/n8_o_rate.md Sec.5 states:

  "> **Theorem 5 (enumeration).** Over every resonance class generated by resonances of
   > sup-norm height `<= 3`: ... | 1 | 107 | `1/6` | ... | 2 | 1795 | `1/4` |"

and the producing script rt_lattice_v1.py decides realisability by
rt_limit_v2.witnesses(M, PMAX), which enumerates e = B alpha over the PARAMETER box
|alpha_i| <= PMAX (the reported run used PMAX = 24).  A class whose smallest witness
needs a larger alpha is then recorded as non-realisable and dropped.

Here realisability is decided exactly, in O(1), by
   (C) the open cone {alpha : B_rho . alpha > 0 for all rho} is nonempty, and
   (G) B alpha = (1,3,5,7) mod 8 is solvable mod 8,
and every class the test accepts is then confirmed by producing an EXPLICIT witness
from a much larger alpha box, with its true maximum speed printed.

usage: python3 tb_class3_v1.py [PMAX_REPORT] [PMAX_BIG]
"""
import sys, itertools
from fractions import Fraction as F
from math import gcd
from functools import reduce

import rt_limit_v2 as RL
import tb_limit_v1 as TB   # exact, DFS-clipped, validated against RL.rank2_limit
from tb_hunt_v3 import plucker, realisable, cell_count

RHO = (1, 3, 5, 7)
PSMALL = int(sys.argv[1]) if len(sys.argv) > 1 else 24
PBIG = int(sys.argv[2]) if len(sys.argv) > 2 else 400


def witness(rows, PMAX, cap=10 ** 7):
    B, r = RL.kernel_basis([list(x) for x in rows])
    best = None
    for al in itertools.product(range(-PMAX, PMAX + 1), repeat=len(B[0])):
        e = tuple(sum(B[i][c] * al[c] for c in range(len(B[0])))
                  for i in range(4))
        if any(x <= 0 for x in e) or max(e) > cap:
            continue
        if any(x % 8 != RHO[i] % 8 for i, x in enumerate(e)):
            continue
        if len(set(e)) != 4 or reduce(gcd, e) != 1:
            continue
        if best is None or max(e) < max(best):
            best = e
    return best


if __name__ == "__main__":
    ADM3 = [v for v in itertools.product(range(-3, 4), repeat=4) if RL.admissible(v)]
    print(f"admissible primitive vectors of height <= 3: {len(ADM3)}")

    # ---------------- rank 1
    seen, r1 = set(), []
    for v in ADM3:
        k, _ = RL.lattice_key([list(v)])
        if k in seen:
            continue
        seen.add(k)
        B, _ = RL.kernel_basis([list(k[0])])
        r1.append((tuple(k[0]), RL.rank1_limit(tuple(k[0]))))
    print(f"\nrank-1 classes at height <= 3 (before any realisability filter): {len(r1)}")
    ok_small = [x for x in r1 if witness([x[0]], 12)]
    ok_big = [x for x in r1 if witness([x[0]], 40)]
    print(f"   with a witness in |alpha| <= 12 : {len(ok_small)}")
    print(f"   with a witness in |alpha| <= 40 : {len(ok_big)}")
    print(f"   max limit = {max(x[1] for x in ok_big)}   "
          f"min limit = {min(x[1] for x in ok_big)}")
    print(f"   limits above 1/6: {sum(1 for x in ok_big if x[1] > F(1,6))}")

    # ---------------- rank 2
    keys = {}
    for i in range(len(ADM3)):
        for j in range(i + 1, len(ADM3)):
            p = plucker(ADM3[i], ADM3[j])
            if p is None or p in keys:
                continue
            keys[p] = (ADM3[i], ADM3[j])
    print(f"\ndistinct 2-planes spanned by two height-<= 3 admissible vectors: {len(keys)}")

    rows = []
    for p, (u, v) in keys.items():
        k, rk = RL.lattice_key([list(u), list(v)])
        if rk != 2:
            continue
        B, _ = RL.kernel_basis([list(r) for r in k])
        rows.append((k, B, realisable(B)))
    real = [r for r in rows if r[2]]
    print(f"   distinct saturated rank-2 lattices: {len(rows)}")
    print(f"   realisable by the exact (C)+(G) test: {len(real)}")

    ws_small = {}
    for k, B, _ in real:
        ws_small[k] = witness(k, PSMALL)
    found_small = [k for k in ws_small if ws_small[k]]
    print(f"   of these, with a witness inside the report's alpha box "
          f"|alpha| <= {PSMALL}: {len(found_small)}")
    missed = [k for k in ws_small if not ws_small[k]]
    print(f"   MISSED by that box: {len(missed)}")

    lims = {}
    heavy = 0
    for k, B, _ in real:
        if cell_count(B) > 4_000_000:
            heavy += 1
            continue
        lims[k] = TB.rank2_limit([list(r) for r in k])
    print(f"   limits computed for {len(lims)} of them (cell-count skips: {heavy})")
    mx = max(lims.values())
    print(f"   MAX limit over ALL realisable height-<=3 rank-2 classes: {mx} = "
          f"{float(mx):.7f}   (report's value over its 1795: 1/4)")
    print(f"   classes with limit > 1/4: "
          f"{sum(1 for v in lims.values() if v > F(1,4))}")
    print(f"   classes with limit > 1/3: "
          f"{sum(1 for v in lims.values() if v > F(1,3))}")

    print(f"\n   the classes the report's box missed, with an explicit witness from "
          f"|alpha| <= {PBIG}:")
    shown = 0
    mxm = F(0)
    nowit = 0
    for k in missed:
        w = witness(k, PBIG)
        lim = lims.get(k)
        if w is None:
            nowit += 1
            continue
        if lim is not None and lim > mxm:
            mxm = lim
        if shown < 12:
            print(f"      {k}  o_inf = {lim}  witness {w}  max speed {max(w)}")
            shown += 1
    print(f"      ... {len(missed)} missed classes; explicit witness found for "
          f"{len(missed) - nowit}, none found in |alpha| <= {PBIG} for {nowit}")
    print(f"      max limit among the missed classes: {mxm} = {float(mxm):.7f}")
